import 'dart:convert';
import 'dart:typed_data';

/// Cleaned, tightly-cropped RGB PNG of the Southern Regional Health Authority /
/// Mandeville Regional Hospital prescription form supplied for the Medqur
/// prototype.
///
/// The source photo is embedded as an ordinary RGB PNG instead of a 1-bit
/// monochrome PNG. That avoids platform/browser decoder differences that could
/// render the form as a grey placeholder while keeping the printed template
/// sharp and deterministic.
///
/// Template reference: SRHA.MRH.CM2013.
const String kPrescriptionTemplatePngBase64 = r'''
iVBORw0KGgoAAAANSUhEUgAAAnMAAARaCAIAAACooWOdAAA3sklEQVR42u3d3ZqjKrcG0KSeuv9bzj6or7NdAhNQ/B/jqDuVGGMMrxMR35/P5wUADPJjEwCA
...TRUNCATED_FOR_BREVITY...RK5CYII=
''';

Uint8List prescriptionTemplatePngBytes() =>
    Uint8List.fromList(base64Decode(kPrescriptionTemplatePngBase64.replaceAll(RegExp(r'\s+'), '')));
